<?php

declare(strict_types=1);

require_once __DIR__ . '/Database.php';
require_once __DIR__ . '/Auth.php';
require_once __DIR__ . '/AppNavigation.php';
require_once __DIR__ . '/AccessPolicy.php';
require_once __DIR__ . '/ProductionContext.php';

final class PlaybillExperience
{
    private const ROUTES=['/playbills','/admin/playbill'];
    public static function handles(string $route):bool{return in_array($route,self::ROUTES,true);}

    public static function render(string $route,string $basePath):never
    {
        $db=Database::connect(dirname(__DIR__));
        Auth::startSession();$user=Auth::currentUser($db);if(!$user)self::redirect(($basePath?:'').'/login');$_SESSION['playbill_csrf']??=bin2hex(random_bytes(24));$production=ProductionContext::selected($db,$user);
        if($route==='/admin/playbill'&&!AccessPolicy::canManagePlaybill($user))self::forbidden();if($_SERVER['REQUEST_METHOD']==='POST'&&$route==='/admin/playbill')self::handlePost($db,$basePath,$user,$production);
        $playbill=$production?self::playbillForProduction($db,(int)$production['id']):null;$canPreview=AccessPolicy::canManagePlaybill($user);if($route==='/playbills'&&$playbill&&$playbill['status']!=='current'&&!$canPreview)$playbill=null;$sections=$playbill?self::sections($db,(int)$playbill['id'],$route==='/admin/playbill'):[];$roster=$production?self::roster($db,(int)$production['id']):[];self::page($route,$basePath,$user,$production,$playbill,$sections,$roster);
    }

    private static function handlePost(PDO $db,string $basePath,array $user,?array $production):never
    {
        if(!hash_equals((string)($_SESSION['playbill_csrf']??''),(string)($_POST['csrf_token']??''))){self::flash('error','Your Playbill session expired. Please try again.');self::redirect($basePath.'/admin/playbill');}if(!$production){self::flash('error','Select an active production before managing its Playbill.');self::redirect($basePath.'/production');}
        try{$action=(string)($_POST['action']??'');if($action==='save_playbill'){self::savePlaybill($db,$user,$production,$_POST);self::flash('success','Playbill details saved.');}elseif($action==='save_section'){self::saveSection($db,$user,$production,$_POST);self::flash('success','Playbill section saved.');}elseif($action==='toggle_section'){self::toggleSection($db,$user,$production,(int)(filter_input(INPUT_POST,'section_id',FILTER_VALIDATE_INT)?:0));self::flash('success','Section visibility updated.');}elseif($action==='publish'){self::changeStatus($db,$user,$production,'current');self::flash('success','Playbill published.');}elseif($action==='archive'){self::changeStatus($db,$user,$production,'archived');self::flash('success','Playbill archived.');}elseif($action==='draft'){self::changeStatus($db,$user,$production,'draft');self::flash('success','Playbill returned to draft.');}else throw new RuntimeException('Choose a valid Playbill action.');}catch(RuntimeException $e){self::flash('error',$e->getMessage());}self::redirect($basePath.'/admin/playbill');
    }

    private static function savePlaybill(PDO $db,array $actor,array $production,array $input):void
    {
        $title=trim((string)($input['display_title']??''));$subtitle=trim((string)($input['subtitle']??''));$cover=trim((string)($input['cover_note']??''));$slug=strtolower(trim((string)($input['public_slug']??'')));$slug=trim(preg_replace('/[^a-z0-9-]+/','-',$slug)?:'','-');if($title===''||mb_strlen($title)>190)throw new RuntimeException('Enter a Playbill title no longer than 190 characters.');if(mb_strlen($subtitle)>255)throw new RuntimeException('Keep the subtitle under 255 characters.');if(mb_strlen($cover)>500)throw new RuntimeException('Keep the cover note under 500 characters.');if($slug===''||mb_strlen($slug)>190)throw new RuntimeException('Enter a valid public slug.');
        $db->beginTransaction();try{$s=$db->prepare('SELECT id,status FROM playbills WHERE production_id=:production LIMIT 1 FOR UPDATE');$s->execute(['production'=>(int)$production['id']]);$existing=$s->fetch();if($existing){$db->prepare('UPDATE playbills SET display_title=:title,subtitle=:subtitle,cover_note=:cover,public_slug=:slug WHERE id=:id')->execute(['title'=>$title,'subtitle'=>$subtitle!==''?$subtitle:null,'cover'=>$cover!==''?$cover:null,'slug'=>$slug,'id'=>(int)$existing['id']]);$id=(int)$existing['id'];$event='playbill.updated';}else{$db->prepare("INSERT INTO playbills (production_id,display_title,subtitle,cover_note,status,public_slug,created_by_user_id) VALUES (:production,:title,:subtitle,:cover,'draft',:slug,:creator)")->execute(['production'=>(int)$production['id'],'title'=>$title,'subtitle'=>$subtitle!==''?$subtitle:null,'cover'=>$cover!==''?$cover:null,'slug'=>$slug,'creator'=>(int)$actor['id']]);$id=(int)$db->lastInsertId();$event='playbill.created';}self::audit($db,(int)$actor['id'],$event,'playbill',$id,'Saved digital Playbill details.',['production_id'=>(int)$production['id'],'slug'=>$slug]);$db->commit();}catch(PDOException $e){if($db->inTransaction())$db->rollBack();if((string)$e->getCode()==='23000')throw new RuntimeException('That public slug is already in use. Choose another.');throw new RuntimeException('The Playbill could not be saved.');}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof RuntimeException)throw $e;throw new RuntimeException('The Playbill could not be saved.');}
    }

    private static function saveSection(PDO $db,array $actor,array $production,array $input):void
    {
        $playbill=self::playbillForProduction($db,(int)$production['id']);if(!$playbill)throw new RuntimeException('Save the Playbill cover details before adding sections.');$id=(int)(filter_input(INPUT_POST,'section_id',FILTER_VALIDATE_INT)?:0);$type=trim((string)($input['section_type']??'custom'));$heading=trim((string)($input['heading']??''));$body=trim((string)($input['body']??''));$order=(int)($input['sort_order']??0);if($heading===''||mb_strlen($heading)>190)throw new RuntimeException('Enter a section heading no longer than 190 characters.');if($body===''||mb_strlen($body)>20000)throw new RuntimeException('Enter section content up to 20,000 characters.');if($type===''||mb_strlen($type)>80)throw new RuntimeException('Choose a valid section type.');
        if($id>0){$s=$db->prepare('UPDATE playbill_sections SET section_type=:type,heading=:heading,body=:body,sort_order=:sort_order WHERE id=:id AND playbill_id=:playbill');$s->execute(['type'=>$type,'heading'=>$heading,'body'=>$body,'sort_order'=>$order,'id'=>$id,'playbill'=>(int)$playbill['id']]);$event='playbill.section_updated';}else{$s=$db->prepare('INSERT INTO playbill_sections (playbill_id,section_type,heading,body,sort_order,active) VALUES (:playbill,:type,:heading,:body,:sort_order,1)');$s->execute(['playbill'=>(int)$playbill['id'],'type'=>$type,'heading'=>$heading,'body'=>$body,'sort_order'=>$order]);$id=(int)$db->lastInsertId();$event='playbill.section_created';}self::audit($db,(int)$actor['id'],$event,'playbill_section',$id,'Saved Playbill section.',['playbill_id'=>(int)$playbill['id'],'production_id'=>(int)$production['id']]);
    }

    private static function toggleSection(PDO $db,array $actor,array $production,int $sectionId):void{$playbill=self::playbillForProduction($db,(int)$production['id']);if(!$playbill||$sectionId<1)throw new RuntimeException('That Playbill section could not be found.');$s=$db->prepare('SELECT id,active FROM playbill_sections WHERE id=:id AND playbill_id=:playbill');$s->execute(['id'=>$sectionId,'playbill'=>(int)$playbill['id']]);$row=$s->fetch();if(!$row)throw new RuntimeException('That section does not belong to this Playbill.');$next=(int)$row['active']?0:1;$db->prepare('UPDATE playbill_sections SET active=:active WHERE id=:id')->execute(['active'=>$next,'id'=>$sectionId]);self::audit($db,(int)$actor['id'],'playbill.section_visibility_changed','playbill_section',$sectionId,'Changed Playbill section visibility.',['active'=>(bool)$next]);}
    private static function changeStatus(PDO $db,array $actor,array $production,string $status):void{if(!in_array($status,['draft','current','archived'],true))throw new RuntimeException('Choose a valid Playbill status.');$playbill=self::playbillForProduction($db,(int)$production['id']);if(!$playbill)throw new RuntimeException('Create the Playbill before changing its publication status.');if($status==='current'&&empty($playbill['public_slug']))throw new RuntimeException('Add a public slug before publishing.');$db->prepare('UPDATE playbills SET status=:status,published_at=:published WHERE id=:id')->execute(['status'=>$status,'published'=>$status==='current'?date('Y-m-d H:i:s'):null,'id'=>(int)$playbill['id']]);self::audit($db,(int)$actor['id'],'playbill.status_changed','playbill',(int)$playbill['id'],'Changed Playbill publication status.',['status'=>$status,'production_id'=>(int)$production['id']]);}
    private static function playbillForProduction(PDO $db,int $productionId):?array{$s=$db->prepare('SELECT pb.*,p.title production_title,p.season FROM playbills pb JOIN productions p ON p.id=pb.production_id WHERE pb.production_id=:production ORDER BY pb.id DESC LIMIT 1');$s->execute(['production'=>$productionId]);return $s->fetch()?:null;}
    private static function sections(PDO $db,int $playbillId,bool $includeInactive=false):array{$s=$db->prepare('SELECT id,section_type,heading,body,sort_order,active FROM playbill_sections WHERE playbill_id=:playbill'.($includeInactive?'':" AND active=1").' ORDER BY sort_order,id');$s->execute(['playbill'=>$playbillId]);return $s->fetchAll();}
    private static function roster(PDO $db,int $productionId):array{$s=$db->prepare("SELECT pm.audience_type,pm.participation_role,CONCAT(u.first_name,' ',u.last_name) name FROM production_memberships pm JOIN users u ON u.id=pm.user_id AND u.active=1 AND u.account_status<>'disabled' WHERE pm.production_id=:production AND pm.status='active' ORDER BY FIELD(pm.audience_type,'student','staff','guardian'),pm.participation_role,u.last_name,u.first_name");$s->execute(['production'=>$productionId]);return $s->fetchAll();}

    private static function publicPage(PDO $db,string $basePath):never{$slug=trim((string)($_GET['slug']??''));$s=$db->prepare("SELECT pb.*,p.title production_title,p.season FROM playbills pb JOIN productions p ON p.id=pb.production_id WHERE pb.public_slug=:slug AND pb.status='current' LIMIT 1");$s->execute(['slug'=>$slug]);$playbill=$s->fetch();if(!$playbill){http_response_code(404);self::renderPublic($basePath,null,[],[]);}$sections=self::sections($db,(int)$playbill['id']);$roster=self::roster($db,(int)$playbill['production_id']);self::renderPublic($basePath,$playbill,$sections,$roster);}

    private static function page(string $route,string $basePath,array $user,?array $production,?array $playbill,array $sections,array $roster):never
    {
        $u=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$staff=AccessPolicy::canManagePlaybill($user);$flash=$_SESSION['playbill_flash']??null;unset($_SESSION['playbill_flash']);$sub=[['label'=>'Overview','href'=>'/production','active'=>false],['label'=>'Schedule','href'=>'/schedule','active'=>false],['label'=>'Resources','href'=>'/resources','active'=>false],['label'=>'Playbill','href'=>'/playbills','active'=>true]];if($staff)$sub[]=['label'=>'Media & sponsors','href'=>'/admin/playbill/media','active'=>false];
        header('Content-Type:text/html;charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Playbill · CTSMD Connect</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/playbill-management.css')?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar($route,$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Production',$route==='/admin/playbill'?'Manage Playbill':'Playbill',$basePath,$sub);?><div class="pb-page"><?php if($flash):?><div class="pb-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?><?php if(!$production):?><section class="pb-empty"><h2>No production selected.</h2><a class="button" href="<?=$u('/production')?>">Choose a production</a></section><?php elseif($route==='/admin/playbill'):?><section class="pb-hero admin"><div><small><?=$e(strtoupper($production['title']))?></small><h2>Build the program people will actually read.</h2></div><span><?=$playbill?$e(strtoupper($playbill['status'])):'NOT CREATED'?></span></section><div class="pb-admin-grid"><form method="post" class="pb-card"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['playbill_csrf'])?>"><input type="hidden" name="action" value="save_playbill"><small>COVER & PUBLIC LINK</small><label>Display title<input name="display_title" maxlength="190" required value="<?=$e((string)($playbill['display_title']??$production['title']))?>"></label><label>Subtitle<input name="subtitle" maxlength="255" value="<?=$e((string)($playbill['subtitle']??$production['season']??''))?>"></label><label>Cover note<textarea name="cover_note" maxlength="500" rows="4"><?=$e((string)($playbill['cover_note']??''))?></textarea></label><label>Public slug<input name="public_slug" maxlength="190" required value="<?=$e((string)($playbill['public_slug']??''))?>"></label><button class="button" type="submit">Save Playbill details</button><?php if($playbill):?><a class="button secondary" href="<?=$u('/admin/playbill/media')?>">Artwork, cast profiles & sponsors</a><?php endif;?></form><form method="post" class="pb-card"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['playbill_csrf'])?>"><input type="hidden" name="action" value="save_section"><small>ADD SECTION</small><label>Type<input name="section_type" maxlength="80" value="custom"></label><label>Heading<input name="heading" maxlength="190" required></label><label>Content<textarea name="body" rows="8" maxlength="20000" required></textarea></label><label>Order<input type="number" name="sort_order" value="10"></label><button class="button" type="submit">Add section</button></form></div><?php if($playbill):?><section class="pb-card"><header><h3>Sections</h3></header><?php foreach($sections as $section):?><article class="pb-section-row"><div><b><?=$e($section['heading'])?></b><small><?=$e($section['section_type'])?> · order <?=(int)$section['sort_order']?></small></div><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['playbill_csrf'])?>"><input type="hidden" name="action" value="toggle_section"><input type="hidden" name="section_id" value="<?=(int)$section['id']?>"><button type="submit"><?=$section['active']?'Hide':'Show'?></button></form></article><?php endforeach;?></section><section class="pb-actions"><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['playbill_csrf'])?>"><?php if($playbill['status']!=='current'):?><button class="button" name="action" value="publish">Publish</button><?php else:?><button name="action" value="draft">Return to draft</button><?php endif;?><button name="action" value="archive">Archive</button></form><?php if($playbill['public_slug']):?><a target="_blank" href="<?=$u('/playbill?slug='.urlencode($playbill['public_slug']))?>">Open public Playbill →</a><?php endif;?></section><?php endif;?><?php else:?><section class="pb-hero"><div><small><?=$e(strtoupper($production['title']))?></small><h2><?=$playbill?$e((string)($playbill['display_title']?:$production['title'])):'Playbill'?></h2></div><?php if($staff):?><a href="<?=$u('/admin/playbill')?>">Edit Playbill →</a><?php endif;?></section><?php if($playbill):self::renderProgramContent($e,$sections,$roster);else:?><section class="pb-empty"><h3>No published Playbill yet.</h3><p><?=$staff?'You can preview unpublished work here once a Playbill exists, or publish it from Playbill editor.':'Staff will publish the Playbill here when it is ready.'?></p></section><?php endif;?><?php endif;?></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }

    private static function renderProgramContent(callable $e,array $sections,array $roster):void{$cast=array_values(array_filter($roster,static fn(array $r):bool=>$r['audience_type']==='student'));$team=array_values(array_filter($roster,static fn(array $r):bool=>$r['audience_type']==='staff'));?><div class="pb-program"><section class="pb-roster"><small>CAST</small><h3>Company</h3><?php foreach($cast as $person):?><div><b><?=$e($person['name'])?></b><span><?=$e((string)$person['participation_role'])?></span></div><?php endforeach;?></section><section class="pb-roster"><small>PRODUCTION TEAM</small><h3>Behind the curtain</h3><?php foreach($team as $person):?><div><b><?=$e($person['name'])?></b><span><?=$e((string)$person['participation_role'])?></span></div><?php endforeach;?></section><?php foreach($sections as $section):?><section class="pb-copy"><small><?=$e(strtoupper(str_replace('_',' ',$section['section_type'])))?></small><h3><?=$e($section['heading'])?></h3><p><?=nl2br($e($section['body']))?></p></section><?php endforeach;?></div><?php}
    private static function renderPublic(string $basePath,?array $playbill,array $sections,array $roster):never{$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');header('Content-Type:text/html;charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$playbill?$e((string)($playbill['display_title']??$playbill['production_title'])):'Playbill not found'?> · CTSMD</title><link rel="stylesheet" href="<?=($basePath?:'')?>/assets/css/app.css"><link rel="stylesheet" href="<?=($basePath?:'')?>/assets/css/playbill-management.css"></head><body class="pb-public"><header class="pb-public-brand">CTSMD <span>PLAYBILL</span></header><?php if(!$playbill):?><main class="pb-public-main"><section class="pb-empty"><h1>Playbill not found.</h1></section></main><?php else:?><main class="pb-public-main"><section class="pb-cover"><small>CHILDREN'S THEATRE OF SOUTHERN MARYLAND</small><h1><?=$e((string)($playbill['display_title']??$playbill['production_title']))?></h1><h2><?=$e((string)($playbill['subtitle']??$playbill['season']??''))?></h2><p><?=$e((string)($playbill['cover_note']??''))?></p></section><?php self::renderProgramContent($e,$sections,$roster);?></main><?php endif;?></body></html><?php exit;}
    private static function audit(PDO $db,int $actor,string $event,string $type,int $id,string $summary,array $metadata):void{$s=$db->prepare('INSERT INTO audit_events (actor_user_id,event_type,subject_type,subject_id,summary,metadata_json) VALUES (:actor,:event,:type,:id,:summary,:metadata)');$s->execute(['actor'=>$actor,'event'=>$event,'type'=>$type,'id'=>$id,'summary'=>$summary,'metadata'=>json_encode($metadata,JSON_THROW_ON_ERROR)]);}
    private static function flash(string $type,string $message):void{$_SESSION['playbill_flash']=['type'=>$type,'message'=>$message];}
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
    private static function forbidden():never{http_response_code(403);header('Content-Type:text/plain; charset=utf-8');echo 'Playbill management permission is required.';exit;}
}